// このファイルは自動生成されたデータです。手で編集しないでください。
// 出典: Natural Earth（world-atlas countries-50m）を簡略化して作成。
// 国名の日本語表記は i18n-iso-countries（ja）に準拠。
// 南極大陸と、描画上ほとんど見えない小さな島は省いています。

export type CountryShape = {
  /** ISO 3166-1 alpha-2（例: JP, FR） */
  code: string;
  /** 日本語の国名 */
  name: string;
  /** 投影後の座標。1つの要素が [x0, y0, x1, y1, ...] の形で1つの輪郭を表す */
  rings: number[][];
};

export const WORLD_MAP_WIDTH = 720;
export const WORLD_MAP_HEIGHT = 280;

// 正距円筒図法（経度・緯度をそのまま比例配分する）。
// 投影後の座標でそのまま内外判定できるので、国の判定にも同じ数値を使える。
const LON_MIN = -180;
const LAT_MAX = 84;
const LAT_MIN = -56;
const SCALE = 2;

/** 緯度経度を世界地図上の位置に変換する。表示範囲の外なら null */
export function projectToWorldMap(lat: number, lng: number): { x: number; y: number } | null {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    return null;
  }
  if (lat > LAT_MAX || lat < LAT_MIN || lng < LON_MIN || lng > 180) {
    return null;
  }

  return {
    x: +((lng - LON_MIN) * SCALE).toFixed(2),
    y: +((LAT_MAX - lat) * SCALE).toFixed(2)
  };
}

